const projects=[...(window.TAMIRLAB_WORKSHOP_PROJECTS||[]),...(window.TAMIRLAB_HOME_REPAIRS||[])];
const featuredIds=['e01','r01','p01','s01','e13','r13','p14','s14'];
projects.sort((a,b)=>{const ai=featuredIds.indexOf(a.id),bi=featuredIds.indexOf(b.id);return (ai<0?999:ai)-(bi<0?999:bi)});
const state={filter:'Tümü',search:'',expanded:false,favorites:new Set(JSON.parse(localStorage.getItem('tamirlab-favorites')||'[]'))};
const grid=document.getElementById('projectGrid');const empty=document.getElementById('emptyState');const toast=document.getElementById('toast');
function cardMarkup(p){return `<article class="project-card" data-id="${p.id}" tabindex="0" role="button" aria-label="${p.title} rehberini aç"><div class="project-visual ${p.visual}"><span class="visual-orb"></span><span class="project-level">${p.level}</span><button class="project-fav ${state.favorites.has(p.id)?'is-fav':''}" data-fav="${p.id}" aria-label="${state.favorites.has(p.id)?'Favorilerden çıkar':'Favoriye ekle'}">${state.favorites.has(p.id)?'♥':'♡'}</button><span class="project-emoji">${p.emoji}</span></div><div class="project-body"><div class="project-tags"><span class="project-tag ${p.tagType==='robotics'?'tag-robotics':p.tagType==='coding'?'tag-coding':p.tagType==='home'?'tag-home':''}">${p.tag}</span></div><h3 class="project-title">${p.title}</h3><p class="project-desc">${p.description}</p><div class="project-meta"><span>◷ ${p.time}</span><strong>${p.difficulty}</strong><span class="meta-arrow">↗</span></div></div></article>`}
function matches(p){const f=state.filter;const levelMatch=['İlkokul','Ortaokul','Lise'].includes(f)?p.level===f:true;const categoryMatch=['Elektronik','Robotik','Programlama','Evde Tamir'].includes(f)?p.category===f: f==='STEM'?p.category==='STEM':true;const searchMatch=(p.title+' '+p.category+' '+p.level+' '+p.description+' '+p.tag+' '+p.materials.join(' ')).toLocaleLowerCase('tr').includes(state.search.toLocaleLowerCase('tr'));return levelMatch&&categoryMatch&&searchMatch}
function render(){let list=projects.filter(matches);if(!state.expanded&&state.filter==='Tümü')list=list.slice(0,8);grid.innerHTML=list.map(cardMarkup).join('');empty.hidden=list.length>0;grid.hidden=list.length===0;}
function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2200)}
function projectDiagram(p){
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const wrap=v=>{const words=String(v).split(/\s+/),lines=[];let line='';for(const word of words){if((line+' '+word).trim().length>18&&line){lines.push(line);line=word}else line=(line+' '+word).trim()}if(line)lines.push(line);return lines.slice(0,2)};
 if(p.id==='e01')return `<section class="modal-section diagram-section"><h3>Bağlantı şeması</h3><p class="diagram-caption">Enerji kapalıyken kur: pil yuvası (+) → anahtar → uygun direnç → LED (A/+ ile K/−) → pil yuvası (−).</p><div class="diagram-frame"><svg viewBox="0 0 760 250" role="img" aria-labelledby="nameCardDiagramTitle nameCardDiagramDesc"><title id="nameCardDiagramTitle">Işıklı isim kartı seri devre şeması</title><desc id="nameCardDiagramDesc">Kapalı AA pil yuvasının artı ucundan anahtara, uygun dirence ve LED anotuna giden; LED katodundan pil yuvasının eksi ucuna dönen tek devre yolu.</desc><rect x="1" y="1" width="758" height="248" rx="18" fill="#fbfaff" stroke="#e9e4f1"/><text x="32" y="36" class="diagram-label">KAPALI AA PİL YUVASI</text><rect x="34" y="64" width="142" height="118" rx="14" fill="#fff" stroke="#7547ff" stroke-width="3"/><rect x="58" y="93" width="38" height="55" rx="8" fill="#fff0a8" stroke="#d1a900" stroke-width="2"/><rect x="111" y="93" width="38" height="55" rx="8" fill="#d9f8f4" stroke="#16a99c" stroke-width="2"/><text x="70" y="126" class="diagram-cell">AA</text><text x="123" y="126" class="diagram-cell">AA</text><text x="157" y="82" class="diagram-mark">+</text><text x="157" y="171" class="diagram-mark">−</text><path d="M176 82 H245" class="wire-positive"/><circle cx="250" cy="82" r="5" fill="#7547ff"/><circle cx="297" cy="82" r="5" fill="#7547ff"/><path d="M250 82 L286 61" class="wire-positive"/><path d="M302 82 H345" class="wire-positive"/><text x="243" y="120" class="diagram-label">ANAHTAR</text><rect x="345" y="64" width="130" height="36" rx="7" fill="#fff0e9" stroke="#ff665e" stroke-width="2"/><text x="362" y="88" class="diagram-component">UYGUN DİRENÇ</text><path d="M475 82 H525" class="wire-positive"/><circle cx="568" cy="82" r="34" fill="#fff9d9" stroke="#f3bd00" stroke-width="3"/><path d="M553 82 H583 M568 67 V97" stroke="#f3bd00" stroke-width="3" stroke-linecap="round"/><path d="M568 116 V161 M568 161 H176 V181" class="wire-return"/><path d="M176 181 H157" class="wire-return"/><text x="530" y="137" class="diagram-label">LED</text><text x="532" y="49" class="diagram-mark">A (+)</text><text x="583" y="103" class="diagram-mark">K (−)</text><text x="34" y="220" class="diagram-note">İki bakır bant yolu birbirine değmesin. Anahtar kapanınca devre tamamlanır.</text><path d="M199 76 l10 6 -10 6" fill="#7547ff"/><path d="M516 76 l10 6 -10 6" fill="#7547ff"/></svg></div><p class="diagram-caption">Şema yön gösterir; direnç değeri ve pil adedi kullandığınız hazır LED kitinin talimatına göre seçilir.</p></section>`;
 if(p.category==='Elektronik')return electronicsDiagram(p,esc);
 if(p.category==='Robotik')return roboticsDiagram(p,esc);
 if(p.category==='Programlama')return programmingDiagram(p,esc);
 if(p.category==='STEM')return stemDiagram(p,esc);
 return repairDiagram(p,esc);
}
function electronicsDiagram(p,esc){
 const map={
  e02:['Pil yuvası','Renk seçici anahtar','Bir LED kolu','Kırmızı / sarı / yeşil'],e03:['Pil yuvası','Basmalı anahtar','Direnç + LED','Aç / kapa ışığı'],e04:['Pil yuvası','Oda anahtarları','LED aydınlatma kolları','Ev maketi'],e05:['Eğitim kartı','RGB renk kanalları','Renk seçimi','Kırmızı + yeşil + mavi'],e06:['Eğitim kartı','İletken hamur pedleri','LED ve akım sınırlama','Açık / kapalı devre'],e07:['Pil + LED kiti','İletken bağlantı','Açık ya da kapalı yol','Işık yanar / sönük'],e08:['Pil yuvası','Yıldız LED noktaları','Anahtar / ortak dönüş','Işık kutusu'],e09:['Güneş hücresi','Işık alanı','LED kiti','Parlaklık gözlemi'],e10:['Pil + LED kiti','İletken iz','Ayrık yol bulmacası','LED yalnızca doğru yolda'],e11:['Pil + LED kiti','Anahtar örnekleri','Aynı LED yükü','Anahtarları karşılaştır'],e12:['Pil + LED kiti','Ön / arka ışık','Kesilmiş sahne kartı','Gölge tiyatrosu'],
  e13:['Eğitim kaynağı','Seri direnç','Breadboard LED','Anot → katot'],e14:['Eğitim kaynağı','Seri / paralel kollar','LED grupları','Parlaklık karşılaştır'],e15:['Eğitim kaynağı','Işık sensörü','Eşik / kontrol','Gece LED’i'],e16:['Eğitim kaynağı','Buton girişi','Süre ölçümü','Tepki süresi'],e17:['Eğitim kaynağı','Sıcaklık sensörü','Ölçüm → gösterim','Sıcaklık değeri'],e18:['Eğitim kaynağı','Nem sensörü','Ölçüm kaydı','Bitki gözlem tablosu'],e19:['Eğitim kaynağı','Buton olayı','Rastgele sayı','LED yüzü / sayı'],e20:['Eğitim kaynağı','Morse zamanlama','LED çıkışı','Kısa / uzun ışık'],e21:['Güneş hücresi','Aydınlatma koşulu','Ölçüm noktaları','Açı / değer tablosu'],e22:['Eğitim kaynağı','Ses sensörü','Seviye eşleme','Gösterge LED’i'],e23:['Eğitim kaynağı','Su seviyesi sensörü','Eşik karşılaştırma','Işık / ses uyarısı'],e24:['Bileşen kartı','Sembol / parça','Görev eşleştirme','Ad + işlev'],e25:['Eğitim kaynağı','Anahtar / sensör','Eşik / uyarı','LED / buzzer'],
  e26:['Eğitim kaynağı','LED + direnç','Lehimli rozet izi','Görsel ışık'],e27:['Eğitim kaynağı','Zamanlama modülü','LED çıkışı','Süreli ışık'],e28:['Işık sensörü','Eğitim kartı girişi','Değer eşleme','Ortam ışığı'],e29:['Sıcaklık + nem','Eğitim kartı girişi','Zaman damgası','Veri kaydı'],e30:['Buton olayı','Rastgele sayı','LED çıkış deseni','Zar yüzü'],e31:['Kontrol sinyali','Transistör anahtarı','Düşük gerilimli yük','Aç / kapa gözlemi'],e32:['Eğitim kaynağı','Direnç üzerinden dolum','Kondansatör','Gerilim / zaman grafiği'],e33:['Güneş paneli','Açı / ışık koşulu','Ölçüm cihazı','Akım-gerilim grafiği'],e34:['Ses sensörü','Örnekleme noktaları','Seviye ölçümü','Anonim sınıf haritası'],e35:['Güvenli eğitim kaynağı','Bileşen / test girişi','Ölçüm kontrolü','Beklenen / görülen'],e36:['Buton girişi','Morse zamanlama','LED çıkışı','Kısa / uzun darbe'],e37:['Sensör girişi','Eşik karşılaştırıcı','Gösterge çıkışı','Normal / uyarı'],e38:['Hata simülatörü','Tek hata değişkeni','Belirti gözlemi','Doğru devreyle kıyas']
 };
 const [source,input,logic,output]=map[p.id]||['Düşük gerilimli eğitim kaynağı','Proje giriş bileşeni','Eğitim kartı / devre','Ölçüm veya gösterge'];
 const visualStart=p.id==='e02'||p.id==='e03'||p.id==='e04'||p.id==='e06'||p.id==='e07'||p.id==='e08'||p.id==='e10'||p.id==='e11'||p.id==='e12';
 const svg=visualStart
  ? `<svg viewBox="0 0 900 330" role="img" aria-label="${esc(p.title)} için düşük gerilimli devre yerleşimi"><rect x="1" y="1" width="898" height="328" rx="18" fill="#fbfaff" stroke="#e9e4f1"/><text x="36" y="35" class="diagram-label">DEVRE YOLU · ENERJİ KAPALIYKEN KUR</text><rect x="38" y="100" width="140" height="104" rx="14" fill="#fff" stroke="#7547ff" stroke-width="3"/><text x="108" y="137" text-anchor="middle" class="diagram-node-label">${esc(source)}</text><text x="108" y="160" text-anchor="middle" class="diagram-note">+ / − uç</text><path d="M178 125 H270" class="wire-positive"/><path d="M178 180 H720 V205 H178" class="wire-return"/><rect x="270" y="85" width="180" height="100" rx="13" fill="#fff" stroke="#ff665e" stroke-width="3"/><text x="360" y="122" text-anchor="middle" class="diagram-node-label">${esc(input)}</text><text x="360" y="147" text-anchor="middle" class="diagram-note">anahtar / bağlantı</text><path d="M450 125 H552" class="wire-positive"/><rect x="552" y="85" width="168" height="100" rx="13" fill="#fff" stroke="#efbd00" stroke-width="3"/><text x="636" y="122" text-anchor="middle" class="diagram-node-label">${esc(logic)}</text><text x="636" y="147" text-anchor="middle" class="diagram-note">LED kolu / seçim</text><path d="M720 125 H805 V180 H720" class="wire-positive"/><circle cx="805" cy="151" r="13" fill="#ffcc58" stroke="#30283e" stroke-width="3"/><text x="450" y="260" text-anchor="middle" class="diagram-component">${esc(output)} · KAPALI DEVREDE AKIM YOLU TAMAMLANIR</text><text x="38" y="305" class="diagram-note">Açık devrede bir bağlantı kesilir; kapalı devrede yol tamamlanır. Pil kutuplarını ve kit yönergesini kontrol et.</text></svg>`
  : `<svg viewBox="0 0 900 360" role="img" aria-label="${esc(p.title)} için bileşen bağlantı şeması"><rect x="1" y="1" width="898" height="358" rx="18" fill="#fbfaff" stroke="#e9e4f1"/><text x="34" y="34" class="diagram-label">İŞLEVSEL BAĞLANTI HARİTASI · PINLER KART MODELİNE GÖRE DEĞİŞİR</text><rect x="38" y="105" width="160" height="105" rx="13" fill="#fff" stroke="#ff665e" stroke-width="3"/><text x="118" y="143" text-anchor="middle" class="diagram-node-label">${esc(source)}</text><text x="118" y="168" text-anchor="middle" class="diagram-note">V+ / GND</text><rect x="275" y="62" width="220" height="180" rx="15" fill="#f0ecff" stroke="#7547ff" stroke-width="3"/><text x="385" y="102" text-anchor="middle" class="diagram-node-label">EĞİTİM KARTI</text><rect x="300" y="122" width="76" height="42" rx="8" fill="#fff" stroke="#16a99c" stroke-width="2"/><text x="338" y="148" text-anchor="middle" class="diagram-note">IN</text><rect x="395" y="122" width="76" height="42" rx="8" fill="#fff" stroke="#ff665e" stroke-width="2"/><text x="433" y="148" text-anchor="middle" class="diagram-note">OUT</text><text x="385" y="205" text-anchor="middle" class="diagram-note">${esc(logic)}</text><rect x="38" y="262" width="220" height="65" rx="12" fill="#fff" stroke="#16a99c" stroke-width="2.5"/><text x="148" y="289" text-anchor="middle" class="diagram-node-label">${esc(input)}</text><text x="148" y="311" text-anchor="middle" class="diagram-note">sensör / buton / panel</text><rect x="620" y="105" width="236" height="105" rx="13" fill="#fff" stroke="#efbd00" stroke-width="3"/><text x="738" y="143" text-anchor="middle" class="diagram-node-label">${esc(output)}</text><text x="738" y="168" text-anchor="middle" class="diagram-note">gösterge / kayıt / yük</text><path d="M198 137 H275" class="wire-positive"/><path d="M258 294 H285 V143 H300" fill="none" stroke="#7547ff" stroke-width="3.5" stroke-dasharray="7 6"/><path d="M495 143 H620" fill="none" stroke="#7547ff" stroke-width="4"/><path d="M198 183 H232 V237 H515 V183 H620" class="wire-return"/><text x="530" y="132" class="diagram-note">çıkış sinyali</text><text x="34" y="345" class="diagram-note">Güç bağlantısını kesmeden kablo değiştirme. Gerçek pin adlarını eğitim kartının üretici şemasından doğrula; şebeke elektriği ve batarya açma yok.</text></svg>`;
 return `<section class="modal-section diagram-section"><h3>${visualStart?'Devre yerleşim şeması':'Bileşen ve sinyal bağlantı şeması'}</h3><p class="diagram-caption"><b>${esc(p.title)}</b> — kaynak, giriş, kontrol ve çıktı bileşenlerinin görevleri.</p><div class="diagram-frame">${svg}</div><p class="diagram-caption">${visualStart?'Renkli çizgi pozitif yolu, turkuaz çizgi dönüş yolunu gösterir. Parçaları yalnızca kullanılan kitin güvenli yönergesine göre bağla.':'Bu işlev şeması pin numarası vermez. Kartın üretici bağlantı şemasını izle; lehim gereken projelerde öğretmen/yetişkin gözetimi kullan.'}</p></section>`;
}
